#!/usr/bin/env bash
# GSZ step148 — premium customer dashboard. Redesigned views/account/dashboard.ejs
# (hero, real stat tiles, contextual verification nudges, one-tap Quick Actions,
# clean recent orders) + routes/account.js gains real counts (orders/delivered/
# trials). Replaces the dashboard view, patches account.js. Idempotent; robust check.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step148-$TS"; TMP=$(mktemp -d)
FILES=(routes/account.js views/account/dashboard.ejs)
echo "==> step148: premium customer dashboard"
mkdir -p "$BK"; for f in "${FILES[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; done
echo "    backup: $BK"
restore(){ echo "!! FAILED — restoring"; for f in "${FILES[@]}"; do cp "$BK/$f" "$GSZ/$f"; done; pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."; }
trap 'restore' ERR
echo "==> writing dashboard + patching account.js"
echo ""  | base64 -d > "$GSZ/views/account/dashboard.ejs"
echo "" | base64 -d > "$TMP/p.js"
node "$TMP/p.js" "$GSZ"
echo "==> validating"; node --check "$GSZ/routes/account.js"
node -e "const ejs=require('$GSZ/node_modules/ejs');ejs.compile(require('fs').readFileSync('$GSZ/views/account/dashboard.ejs','utf8'),{filename:'d'});console.log('    ejs ok')"
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000; for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] && echo "    homepage 200: OK (after ${i}s)" || { echo "    homepage $CODE"; false; }
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step148 OK ✅  New premium account dashboard — stat tiles, one-tap Quick Actions, clean orders, and verification nudges that only show when needed. (Hard-refresh to see it.)"
